import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(here, "../../..");
const validatorJs = path.join(repoRoot, "packages/protocol/dist/diagram-validator.js");
const target = path.join(repoRoot, "packages/hub/skills/diagram-design/scripts/check-diagram.mjs");

export function buildStandaloneDiagramCheckerSource(compiledValidatorSource) {
  const core = compiledValidatorSource.replace(/\/\/# sourceMappingURL=.*$/gm, "").trim();
  const cli = `
// --- Standalone zero-dependency CLI entrypoint (auto-synced from @kulo/protocol) ---
import fs from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";

function runCli(argv) {
  const args = argv.slice(2);
  let strict = false;
  const files = [];
  for (const arg of args) {
    if (arg === "--strict") strict = true;
    else if (arg === "-h" || arg === "--help") {
      console.log("Usage: node check-diagram.mjs [--strict] <file.svg|file.html> [...]");
      return 0;
    } else if (!arg.startsWith("-")) {
      files.push(arg);
    }
  }
  if (!files.length) {
    console.error("Usage: node check-diagram.mjs [--strict] <file.svg|file.html> [...]");
    return 2;
  }
  let failed = false;
  const report = [];
  for (const file of files) {
    const resolved = path.resolve(file);
    const content = fs.readFileSync(resolved, "utf8");
    const isHtml = /\\.html?$/i.test(resolved) || /^\\s*(?:<!doctype\\s+html|<html\\b)/i.test(content);
    const svgs = isHtml ? extractInlineSvgsFromHtml(content) : [content];
    if (isHtml && /<link\\b[^>]+href\\s*=\\s*["']https?:\\/\\//i.test(content)) {
      failed = true;
      report.push({ file, ok: false, errors: ["HTML contains external <link href=http(s)://...>; inline or use system fonts."] });
      continue;
    }
    if (!svgs.length) {
      report.push({ file, ok: true, svgCount: 0, note: "No inline <svg> elements found." });
      continue;
    }
    const items = svgs.map((svg, idx) => {
      const r = validateAndNormalizeDiagramSvg(svg, { strict });
      if (!r.ok) failed = true;
      return {
        index: idx + 1,
        ok: r.ok,
        stats: r.stats,
        autoFixed: r.autoFixed,
        errors: r.errors,
        warnings: r.warnings,
      };
    });
    report.push({ file, ok: items.every((x) => x.ok), svgCount: svgs.length, items });
  }
  console.log(JSON.stringify({ ok: !failed, strict, results: report }, null, 2));
  return failed ? 1 : 0;
}

if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {
  process.exit(runCli(process.argv));
}
`;
  return `#!/usr/bin/env node\n// Generated by packages/hub/scripts/sync-diagram-checker.mjs from @kulo/protocol — do not edit by hand.\n${core}\n${cli}`;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const compiled = fs.readFileSync(validatorJs, "utf8");
  const next = buildStandaloneDiagramCheckerSource(compiled);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  const prev = fs.existsSync(target) ? fs.readFileSync(target, "utf8") : null;
  if (prev !== next) {
    fs.writeFileSync(target, next, { mode: 0o755 });
    console.log(`Synced ${path.relative(repoRoot, target)}`);
  }
}
